<template><section class="workspace"><div class="panel"><h2>资产包</h2><p>导出当前主世界书全部资产，或安装版本化资产包。</p><div class="actions"><button @click="exportAll">导出全部资产</button><label class="file">导入资产包<input type="file" accept="application/json" @change="importFile"/></label></div></div><div class="panel"><h2>加入运行角色</h2><p>只写入当前楼层，不修改世界书与关注列表。</p><div class="role-list"><button v-for="role in roles" :key="role.id" @click="add(role.id)"><strong>{{role.entry.key}}</strong><span>{{role.entry.type}}</span></button></div></div><div v-if="conflicts.length" class="dialog"><h3>资产冲突</h3><div v-for="item in conflicts" :key="item.category+item.id" class="conflict"><span>{{item.category}} · {{item.id}}</span><select v-model="decisions[`${item.category}:${item.id}`]"><option value="overwrite">覆盖</option><option value="skip">跳过</option><option value="copy">复制并重映射</option></select></div><button @click="install">确认安装</button><button @click="cancelImport">取消</button></div></section></template>
<script setup lang="ts">import{computed,ref}from'vue';import{addRoleToRuntime}from'../assets/runtimeRole';import{createPackage,downloadPackage,listConflicts,mergePackage,parsePackage,type PackageConflict}from'../assets/package';import{saveScenarioSource}from'../assets/repository';import{assetsOf,type WorkshopCategory}from'../assets/model';import type{PackageConflictDecision,ScenarioSourceBundle,WorkshopPackage}from'../scenario/types';
const props=defineProps<{source:ScenarioSourceBundle}>(),emit=defineEmits<{changed:[];message:[value:{text:string;error?:boolean}]}>();const pending=ref<WorkshopPackage>(),conflicts=ref<PackageConflict[]>([]),decisions=ref<Record<string,PackageConflictDecision>>({});const roles=computed(()=>Object.entries(props.source.registries.角色).map(([id,entry])=>({id,entry})).filter(x=>x.entry.type==='主要角色'||x.entry.type==='次要角色'));
function exportAll(){const selection=Object.fromEntries(Object.entries(assetsOf(props.source)).map(([c,v])=>[c,Object.keys(v)]))as Record<WorkshopCategory,string[]>;downloadPackage(createPackage(props.source,selection))}async function importFile(e:Event){try{const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;pending.value=parsePackage(await file.text());conflicts.value=listConflicts(props.source,pending.value);decisions.value=Object.fromEntries(conflicts.value.map(c=>[`${c.category}:${c.id}`,'skip']));if(!conflicts.value.length)await install();input.value=''}catch(c){emit('message',{text:c instanceof Error?c.message:String(c),error:true})}}async function install(){if(!pending.value)return;try{await saveScenarioSource(mergePackage(props.source,pending.value,decisions.value));emit('message',{text:'资产包已安装。'});cancelImport();emit('changed')}catch(c){emit('message',{text:c instanceof Error?c.message:String(c),error:true})}}function cancelImport(){pending.value=undefined;conflicts.value=[];decisions.value={}}async function add(id:string){const role=props.source.registries.角色[id];try{let r=await addRoleToRuntime(role);if(r==='conflict'&&confirm(`角色 ${role.key} 已存在，是否完整覆盖？`))r=await addRoleToRuntime(role,true);emit('message',{text:r==='conflict'?'已取消覆盖。':'角色已加入当前运行剧本。'})}catch(c){emit('message',{text:c instanceof Error?c.message:String(c),error:true})}}</script>
<style scoped>.workspace{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.panel,.dialog{padding:18px;background:#1d1f20;border:1px solid #454239}.panel p{margin:8px 0 14px;color:#aaa294}.actions,.role-list{display:flex;gap:8px;flex-wrap:wrap}.file{padding:8px 12px;border:1px solid #5a554a;cursor:pointer}.file input{display:none}.role-list button{display:flex;flex-direction:column;align-items:flex-start}.role-list span{color:#aaa294;font-size:12px}.dialog{grid-column:1/-1}.conflict{display:flex;justify-content:space-between;gap:12px;margin:8px 0}@media(max-width:700px){.workspace{grid-template-columns:1fr}}</style>
